<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { Search, Download, Radio, Settings, ArrowUpRight, ArrowRight, Plus, X, RefreshCw, LogOut,
  Film, Compass, Link, Folder, Tv, ChevronRight, Pause, Play, Trash2, CheckCircle2, AlertCircle, Loader2 } from 'lucide-vue-next'

import tmdbLogo from './assets/tmdb-logo.svg'
import Discover from './Discover.vue'
import MediaDetail from './MediaDetail.vue'
import ResourceSearch from './ResourceSearch.vue'
import SettingsPage from './SettingsPage.vue'
import MediaPicker from './MediaPicker.vue'
import TaskNaming from './TaskNaming.vue'
import MagnetPicker from './MagnetPicker.vue'
import NamingPreview from './NamingPreview.vue'
import Subscriptions from './Subscriptions.vue'
import FolderPicker from './FolderPicker.vue'
import type {MagnetSelection, Media, Naming, NamingPreviewReference, Resource, SearchSource} from './types'
type Task = {id:string;title:string;kind:string;state:string;target:string;progress:number;error?:string;updated:number;can_change_target:boolean;events?:{state:string;created:number;message?:string}[];naming?:Naming|null;staging?:string;selection?:{selected_count:number;retained_count:number;download_staging?:string}|null;subscription?:{id:string;episode:number}|null}
type Channel = {id:string;peer:string;title:string;mode:"api"|"public_web";last_synced:number;enabled:number;status:string;count:number;complete:number;error?:string;wait_until:number}
type ShareItem = {id:string;name:string;is_dir:boolean;size:number}
const nav = [{id:'discover',name:'发现',icon:Compass},{id:'search',name:'资源搜索',icon:Search},{id:'subscriptions',name:'追番订阅',icon:Tv},{id:'tasks',name:'入库任务',icon:Download},{id:'channels',name:'Telegram 频道',icon:Radio},{id:'settings',name:'设置',icon:Settings}]
const currentHash=ref(window.location.hash||'#/discover')
const routeMedia=computed(()=>{const match=currentHash.value.match(/^#\/media\/(movie|tv)\/([1-9]\d*)$/);return match?{type:match[1] as 'movie'|'tv',id:Number(match[2])}:null})
let discoveryScroll=0
function navigate(id:string){if(page.value==='discover')discoveryScroll=window.scrollY;window.location.hash='/'+id}
const page=computed({get:()=>routeMedia.value?'media':nav.some(n=>'#/'+n.id===currentHash.value)?currentHash.value.slice(2):'discover',set:navigate})
function updateHash(){currentHash.value=window.location.hash||'#/discover'}
function openMedia(media:Pick<Media,'type'|'id'>){navigate('media/'+media.type+'/'+media.id)}
const searchSeed=ref(''), animeTab=ref(0)
function searchTitle(title:string){searchSeed.value=title;navigate('search')}
watch(currentHash,async()=>{if(page.value!=='search')searchSeed.value='';await nextTick();window.scrollTo(0,page.value==='discover'?discoveryScroll:0)})
const authenticated = ref(false), configured = ref(true), ready = ref(false), setupMode = ref('browser')
const password = ref(''), authBusy = ref(false), notice = ref(''), error = ref('')
const sourceCatalog = ref<SearchSource[]>([])
const searchSources = computed(()=>sourceCatalog.value.filter(source=>(settings.value.enabled_search_sources||[]).includes(source.id)))
const authMessage = ref('')
const tasks = ref<Task[]>([]), channels = ref<Channel[]>([]), settings = ref<Record<string,any>>({})
const busy = ref(false), dialogs = ref<{id:string;title:string;username?:string}[]>([]), channelPeer = ref('')
const channelMode = ref<'public_web'|'api'>('public_web')
const selected = ref<Resource|null>(null), target = ref(''), folderEditing = ref(false)
const shareItems = ref<ShareItem[]>([]), shareSelection = ref<string[]>([]), sharePreviewed = ref(false), submitBusy = ref(false)
const selectedMediaTitle=ref(''), autoNaming=ref(false)
const namingApproval=ref<NamingPreviewReference|null>(null), namingBlocked=ref(false)
const namingInput=computed(()=>({link:selected.value?.link||'',password:selected.value?.password||'',selected_ids:sharePreviewed.value?shareSelection.value:[],magnet_selection:selected.value?.kind==='magnet'?magnetSelection.value:null,media:selected.value?.media||null,resolution:selected.value?.resolution||null}))
watch(autoNaming,()=>{namingApproval.value=null;namingBlocked.value=false})
const magnetSelection=ref<MagnetSelection|null>(null), magnetReady=ref(false)
// Library layout: the server names the title folder created inside the chosen category directory.
const layoutFolder=ref('')
let layoutGeneration=0
watch(()=>autoNaming.value&&selected.value?.media?`${selected.value.media.type}/${selected.value.media.id}`:'',async key=>{const token=++layoutGeneration;layoutFolder.value='';if(!key)return;const [type,id]=key.split('/');try{const data=await api<{folder:string|null}>(`/naming/layout?media_type=${type}&media_id=${id}`);if(token===layoutGeneration)layoutFolder.value=data.folder||''}catch{/* The preview line is optional. */}})
const nestedTarget=computed(()=>{const name=target.value.split('/').filter(Boolean).pop()||'';return !!layoutFolder.value&&!!name&&layoutFolder.value.startsWith(name)})
const manual = ref(false), manualLink = ref(''), manualTitle = ref(''), detail = ref<Task|null>(null), renameTarget = ref('')
let ticker:ReturnType<typeof setInterval>|undefined, authGeneration=0
const labels:Record<string,string> = {queued:'等待处理',preparing:'准备目录',ready_submit:'等待提交',reconciling:'核对提交结果',downloading:'115 离线下载',transferring:'确认文件到位',selecting_files:'整理选中文件',placing:'整理到媒体库',selected_ready:'核对选中文件',naming_planning:'规划规范名称',naming_analyzing:'正在识别命名信息',naming_review:'等待确认命名',renaming:'重命名并核对文件',organizing:'整理到媒体目录',moving:'核对移动结果',scan_queued:'等待 STRM 扫描',scanning:'同步 STRM',notifying:'通知 Emby',completed:'已入库，已通知 Emby',needs_attention:'需要处理',canceled:'已取消'}
const activeCount = computed(()=>tasks.value.filter(t=>!['completed','canceled','needs_attention','naming_review'].includes(t.state)).length)
const enabledChannels = computed(()=>channels.value.filter(c=>c.enabled).length)
const incomplete = computed(()=>channels.value.some(c=>c.enabled&&!c.complete))
const formatDate = (s?:string)=>s?new Date(s).toLocaleDateString('zh-CN'):'未知'
const formatTime = (n:number)=>new Date(n*1000).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})
const formatBytes = (n:number)=>n ? (n/1024**3>=1?(n/1024**3).toFixed(1)+' GB':(n/1024**2).toFixed(1)+' MB'):'未知'

async function api<T=any>(path:string, method='GET', body?:unknown, signal?:AbortSignal):Promise<T> {
  const generation = authGeneration
  const response = await fetch('/api/v1'+path,{method,signal,credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)})
  const data = response.status===204?null:await response.json()
  if (!response.ok) { if(response.status===401&&path!=='/auth/login'&&generation===authGeneration) resetAuthentication(); throw Object.assign(new Error(data.detail||'请求失败'),{status:response.status,retry:response.headers.has('Retry-After')}) }
  return data
}
async function action(fn:()=>Promise<void>) { error.value='';busy.value=true;try {await fn()} catch(e:any){error.value=e.message} finally {busy.value=false} }
function toast(text:string){notice.value=text;setTimeout(()=>notice.value='',4500)}
async function load(){const [s,t,c,providers]=await Promise.all([api('/settings'),api('/tasks'),api('/channels'),api<SearchSource[]>('/sources')]);settings.value=s;tasks.value=t;channels.value=c;sourceCatalog.value=providers;target.value=s.last_target}
async function login(){authBusy.value=true;error.value='';try{await api(configured.value?'/auth/login':'/auth/setup','POST',{password:password.value});password.value='';configured.value=true;authGeneration++;await load();authMessage.value='';authenticated.value=true}catch(e:any){error.value=e.message}finally{authBusy.value=false}}
function resetAuthentication(message='登录已失效，请重新登录'){authGeneration++;authenticated.value=false;password.value='';authMessage.value=message;error.value='';selected.value=null;manual.value=false;detail.value=null;tasks.value=[];channels.value=[];settings.value={};sourceCatalog.value=[]}
async function logout(){await api('/auth/logout','POST',{});resetAuthentication('')}
function acceptDetail(next:Task){const current=detail.value;if(!current||current.id!==next.id||next.updated<current.updated||(next.naming?.revision||0)<(current.naming?.revision||0))return;detail.value=next}
async function poll(){if(!authenticated.value)return;const generation=authGeneration;try{const [nextTasks,nextChannels]=await Promise.all([api('/tasks'),api('/channels')]);if(generation!==authGeneration||!authenticated.value)return;tasks.value=nextTasks;channels.value=nextChannels;if(detail.value){const nextDetail=await api('/tasks/'+detail.value.id);if(generation===authGeneration&&authenticated.value)acceptDetail(nextDetail)}}catch{}}
function choose(resource:Resource){magnetSelection.value=null;magnetReady.value=false;autoNaming.value=true;namingApproval.value=null;namingBlocked.value=false;selected.value={...resource,media:resource.media?{...resource.media}:undefined};selectedMediaTitle.value='';folderEditing.value=false;target.value=settings.value.last_target||settings.value.media_root;shareItems.value=[];shareSelection.value=[];sharePreviewed.value=false}
async function preview(){if(!selected.value)return;await action(async()=>{shareItems.value=await api('/shares/preview','POST',{link:selected.value!.link,password:selected.value!.password||''});shareSelection.value=shareItems.value.map(i=>i.id);sharePreviewed.value=true})}
async function submit(){if(!selected.value||namingBlocked.value)return;if(selected.value.kind==='magnet'&&!magnetReady.value){error.value='请至少勾选一个视频文件';return}if(autoNaming.value&&!selected.value.media){error.value='请关联 TMDB 影片，或取消勾选自动规范命名';return}if(sharePreviewed.value&&!shareSelection.value.length){error.value='请至少选择一项分享内容';return}submitBusy.value=true;error.value='';try{const r=selected.value;const task=await api('/tasks','POST',{link:r.link,title:r.title,password:r.password||'',target:target.value,selected_ids:sharePreviewed.value?shareSelection.value:[],sources:r.sources,magnet_selection:r.kind==='magnet'?magnetSelection.value:undefined,auto_naming:autoNaming.value,naming_preview:autoNaming.value?namingApproval.value||undefined:undefined,media:autoNaming.value?r.media:undefined,resolution:autoNaming.value?r.resolution:undefined});selected.value=null;settings.value.last_target=target.value;await poll();toast(task.state==='completed'?'该资源已入库':'任务已添加，可在入库任务中查看');page.value='tasks'}catch(e:any){error.value=e.message}finally{submitBusy.value=false}}
async function addManual(){if(!manualLink.value.trim())return;const resource:Resource={key:'',link:manualLink.value.trim(),title:manualTitle.value.trim()||'手动添加资源',kind:manualLink.value.startsWith('magnet:')?'magnet':'share',sources:[]};manual.value=false;await choose(resource);manualLink.value='';manualTitle.value=''}
async function taskAction(t:Task, kind:string){await action(async()=>{await api('/tasks/'+t.id+'/'+kind,'POST',{});await poll();toast(kind==='cancel'?'本地流程已停止，已生成文件保留':'已继续处理任务')})}
async function showTask(t:Pick<Task,'id'>){await action(async()=>{detail.value=await api('/tasks/'+t.id);renameTarget.value=detail.value!.target})}
async function refreshDetail(){if(detail.value)acceptDetail(await api('/tasks/'+detail.value.id));await poll()}
async function changeTarget(){if(!detail.value)return;await action(async()=>{await api('/tasks/'+detail.value!.id+'/retry','POST',{target:renameTarget.value});detail.value=null;await poll()})}
async function addChannel(peer=channelPeer.value,mode=channelMode.value){await action(async()=>{await api('/channels','POST',{peer,mode});channelPeer.value='';channels.value=await api('/channels');toast(mode==='public_web'?'频道已添加，开始回溯网页可见历史':'频道已添加，开始回溯 API 可访问历史')})}
async function toggleChannel(c:Channel){await action(async()=>{await api('/channels/'+c.id,'PATCH',{enabled:!c.enabled});await poll()})}
async function deleteChannel(c:Channel){if(!confirm('移除频道“'+c.title+'”及本地索引？入库文件会保留。'))return;await action(async()=>{await api('/channels/'+c.id,'DELETE');await poll()})}
onMounted(async()=>{window.addEventListener('hashchange',updateHash);if(!window.location.hash)history.replaceState(null,'','#/discover');try{const state=await api('/auth/state');configured.value=state.configured;setupMode.value=state.setup_mode||'browser';authenticated.value=state.authenticated;if(state.authenticated)await load()}catch(e:any){error.value=e.message}finally{ready.value=true}ticker=setInterval(poll,5000)})
onUnmounted(()=>{window.removeEventListener('hashchange',updateHash);if(ticker)clearInterval(ticker)})
</script>

<template>
  <div v-if="!ready" class="loading-screen"><Loader2 class="spin"/> 正在连接 MediaLink</div>
  <div v-else-if="!authenticated" class="login-screen">
    <div class="login-story"><div class="brand"><span class="brand-icon"><Film :size="23"/></span>MediaLink<span class="brand-dot">.</span></div><div><span class="eyebrow">YOUR PERSONAL MEDIA PIPELINE</span><h1>找到好资源。<br>接下来，交给我们。</h1><p>汇聚影视网站与 Telegram 频道资源，<br>一键送入 115，连接你的 Emby 媒体库。</p><div class="flow"><span>搜索</span><ArrowRight/><span>115</span><ArrowRight/><span>Emby</span></div></div><small>本机运行 · 个人媒体库</small></div>
    <form class="login-card" @submit.prevent="login"><span class="eyebrow">WELCOME TO MEDIALINK</span><h2>{{ configured?'欢迎回来':'设置你的访问密码' }}</h2><p>{{ configured?'登录后搜索资源、管理入库任务。':setupMode==='cli'?'请先在部署终端初始化访问密码，完成后刷新此页面。':'首次设置请从这台 Mac 打开页面。密码用于电脑和手机访问。' }}</p><p v-if="authMessage" class="auth-message" role="status">{{authMessage}}</p><label v-if="configured||setupMode!=='cli'">个人访问密码<input v-model="password" type="password" autocomplete="current-password" minlength="8" required placeholder="至少 8 个字符"/></label><p v-if="error" class="error-text">{{error}}</p><button v-if="configured||setupMode!=='cli'" class="primary wide" :disabled="authBusy"><Loader2 v-if="authBusy" :size="18" class="spin"/>{{configured?'登录 MediaLink':'设置密码并进入'}}<ArrowRight :size="18"/></button><small>账号凭据保存在服务端的专用凭据存储中</small></form>
  </div>
  <div v-else class="shell" :class="{'is-cinema':page==='discover'||page==='media'}">
    <aside class="sidebar"><div class="brand"><span class="brand-icon"><Film :size="22"/></span>MediaLink<span class="brand-dot">.</span></div><div class="nav-label">工作空间</div><nav><button v-for="item in nav" :key="item.id" :class="{active:page===item.id}" @click="page=item.id"><component :is="item.icon" :size="19"/><span>{{item.name}}</span><span v-if="item.id==='tasks'&&activeCount" class="nav-count">{{activeCount}}</span></button></nav><div class="sidebar-bottom"><div class="pipeline-note"><span class="online-dot"/> 本机运行<div>115 → STRM → Emby</div></div><button class="logout" @click="action(logout)"><LogOut :size="17"/>退出登录</button></div></aside>
    <main><header class="topbar"><span>个人媒体工作空间 <ChevronRight :size="14"/> <b>{{page==='media'?'影片详情':nav.find(n=>n.id===page)?.name}}</b></span><div><span class="online-dot"/> 本机服务 <span class="avatar">M</span></div></header>
      <div class="content">
        <div v-if="error" class="banner error"><AlertCircle :size="18"/><span>{{error}}</span><button @click="error=''"><X :size="16"/></button></div>
        <Discover v-show="page==='discover'" :request="api" :configured="!!settings.tmdb_configured" @open="openMedia" @search="searchTitle" @settings="page='settings'" @subscriptions="page='subscriptions'" :anime-tab="animeTab"/>
        <Subscriptions v-if="page==='subscriptions'" :request="api" @task="showTask({id:$event})" @discover="animeTab++;page='discover'"/>
        <MediaDetail v-if="page==='media'&&routeMedia" :request="api" :type="routeMedia.type" :id="routeMedia.id" :sources="searchSources" :configured="!!settings.tmdb_configured" @unauthorized="resetAuthentication()" @choose="choose" @open="openMedia" @back="page='discover'" @settings="page='settings'"/>
        <section v-if="page==='search'"><div class="page-heading"><div><span class="eyebrow">DISCOVER & COLLECT</span><h1>下一部好片，从这里开始<span>.</span></h1><p>借助中英文片名，搜索网站与频道资源。</p></div><button class="outline" @click="manual=true"><Plus :size="17"/>粘贴链接</button></div>
          <div v-if="incomplete" class="banner coverage"><Radio :size="17"/><span>频道历史正在同步，搜索覆盖已完成索引的消息。</span><button @click="page='channels'">查看进度 <ArrowUpRight :size="14"/></button></div>
          <ResourceSearch :key="searchSeed" :initial="searchSeed" :default-use-tmdb="settings.default_use_tmdb" :request="api" :sources="searchSources" :configured="!!settings.tmdb_configured" @unauthorized="resetAuthentication()" @choose="choose" @open="openMedia" @settings="page='settings'"/>
        </section>
        <section v-if="page==='tasks'"><div class="page-heading"><div><span class="eyebrow">YOUR COLLECTION IN MOTION</span><h1>入库任务<span>.</span></h1><p>从资源到媒体库，每一步都有迹可循。</p></div><button class="outline" @click="action(poll)"><RefreshCw :size="16"/>刷新</button></div><div class="task-summary"><span><b>{{activeCount}}</b> 正在处理</span><span><b>{{tasks.filter(t=>t.state==='completed').length}}</b> 已完成</span><span><b>{{tasks.filter(t=>['needs_attention','naming_review'].includes(t.state)).length}}</b> 需要处理</span></div><div v-if="!tasks.length" class="empty-state"><Download :size="38"/><h3>你的第一条入库任务</h3><p>搜索资源或粘贴磁力／115 分享链接。</p><button class="text-button" @click="page='search'">去搜索 <ArrowRight :size="15"/></button></div><div v-else class="task-list"><article v-for="t in tasks" :key="t.id" class="task-card"><div class="task-top"><span class="task-status" :class="t.state"><CheckCircle2 v-if="t.state==='completed'" :size="16"/><AlertCircle v-else-if="['needs_attention','naming_review'].includes(t.state)" :size="16"/><Loader2 v-else-if="t.state!=='canceled'" class="spin" :size="16"/>{{labels[t.state]||t.state}}</span><small>{{formatTime(t.updated)}}</small></div><h3>{{t.title}}</h3><span v-if="t.subscription" class="subscription-tag"><Tv :size="12"/>追番 · 第 {{t.subscription.episode}} 集</span><p class="task-path"><Folder :size="14"/>{{t.target}}</p><div class="progress-track"><i :style="{width:Math.max(3,t.progress)+'%'}"/></div><p v-if="t.error" class="task-error">{{t.error}}</p><div class="task-actions"><button class="text-button" @click="showTask(t)">查看详情 <ArrowUpRight :size="13"/></button><div><button v-if="!['completed','canceled','naming_review','naming_analyzing'].includes(t.state)" class="text-button" @click="taskAction(t,'retry')"><RefreshCw :size="13"/>重试当前阶段</button><button v-if="!['completed','canceled'].includes(t.state)" class="text-button muted" @click="taskAction(t,'cancel')">取消</button></div></div></article></div></section>
        <section v-if="page==='channels'"><div class="page-heading channel-heading"><div><span class="eyebrow">YOUR SOURCES, CONNECTED</span><h1>Telegram 频道<span>.</span></h1><p>公开频道无需 API，后台回溯网页可见历史并定时更新。</p></div><button v-if="settings.telegram_connected" class="outline" :disabled="busy" @click="action(async()=>{dialogs=await api('/telegram/dialogs')})"><Plus :size="16"/>API 模式：已加入频道</button></div><div v-if="channelMode==='api'&&!settings.telegram_connected" class="banner coverage"><Radio :size="17"/>个人账号 API 模式需要先登录 Telegram。<button @click="page='settings'">前往设置 <ArrowRight :size="14"/></button></div><form class="channel-add" @submit.prevent="addChannel()"><Radio :size="19"/><select v-model="channelMode" aria-label="频道同步方式"><option value="public_web">公开网页 · 无需 API</option><option value="api">个人账号 API</option></select><input v-model="channelPeer" :placeholder="channelMode==='public_web'?'输入 @频道名或 t.me 公开频道链接':'输入 @频道名、t.me 链接或频道 ID'" aria-label="Telegram 频道"/><button class="primary" :disabled="busy||!channelPeer">添加频道</button></form><div v-if="dialogs.length" class="dialog-picker"><button v-for="d in dialogs" :key="d.id" @click="addChannel(d.id,'api')"><Plus :size="14"/>{{d.title}}</button><button class="text-button" @click="dialogs=[]">收起</button></div><div v-if="!channels.length" class="empty-state"><Radio :size="38"/><h3>让你的频道成为可搜索的资源库</h3><p>添加公开频道即可开始索引正文、隐藏链接和提取码，无需申请个人 API。</p></div><div class="channel-grid"><article v-for="c in channels" :key="c.id" class="channel-card"><div class="channel-top"><span class="channel-avatar"><Radio :size="22"/></span><button class="icon-button" @click="deleteChannel(c)" aria-label="移除频道"><Trash2 :size="16"/></button></div><h3>{{c.title}}</h3><p>{{c.mode==='public_web'?'公开网页 · @'+c.peer:'个人账号 API · '+c.id}}</p><div class="channel-count">{{c.count.toLocaleString()}} <small>条已索引消息</small></div><div class="channel-state"><span class="online-dot" :class="{paused:!c.enabled}"/>{{c.status}}</div><p class="channel-updated">最后更新：{{c.last_synced?formatTime(c.last_synced):'尚未同步'}}</p><p v-if="c.mode==='public_web'" class="channel-note">仅覆盖网页可见消息，缺失消息不代表已删除。</p><p v-if="c.error" class="error-text">{{c.error}}</p><button class="outline wide" @click="toggleChannel(c)"><Pause v-if="c.enabled" :size="14"/><Play v-else :size="14"/>{{c.enabled?'暂停同步':'继续同步'}}</button></article></div></section>
        <SettingsPage v-if="page==='settings'" :request="api" :values="settings" :sources="sourceCatalog" @saved="settings=$event" @channels="page='channels'" @password-changed="resetAuthentication('密码已修改，请使用新密码重新登录')"/>
      </div><footer>MediaLink <span>·</span> 你的资源，你的媒体库<details class="tmdb-credit"><summary>关于影视资料</summary><a href="https://www.themoviedb.org" target="_blank" rel="noopener noreferrer"><img :src="tmdbLogo" alt="TMDB"/></a><p>This product uses the TMDB API but is not endorsed or certified by TMDB.</p></details></footer>
    </main>
  </div>
  <div v-if="notice" class="toast"><CheckCircle2 :size="18"/>{{notice}}</div>
  <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><div class="modal wide-modal"><button class="modal-close icon-button" @click="selected=null"><X :size="20"/></button><span class="eyebrow">ADD TO YOUR LIBRARY</span><h2>入库 115</h2><p class="selected-title">{{selected.title}}</p><MagnetPicker v-if="selected.kind==='magnet'" :link="selected.link" :request="api" v-model="magnetSelection" :disabled="submitBusy||busy" :auto-naming="autoNaming" @ready="magnetReady=$event"/><label class="auto-naming-option"><input v-model="autoNaming" type="checkbox" :disabled="submitBusy||busy"/>自动规范命名</label><MediaPicker v-if="autoNaming" :request="api" v-model="selected.media" v-model:title="selectedMediaTitle" :disabled="submitBusy||busy"/><label v-if="autoNaming&&selected.media?.type==='movie'">资源清晰度（可选）<select v-model="selected.resolution" aria-label="入库电影清晰度"><option :value="undefined">自动识别</option><option v-for="q in ['480P','576P','720P','1080P','1080I','2160P','4320P','4K','8K']" :key="q">{{q}}</option></select></label><label v-if="selected.kind==='share'">分享提取码<input v-model="selected.password" placeholder="消息未提供时在这里填写" maxlength="32"/></label><label>{{autoNaming?'入库分类目录':'入库目录'}}<input v-model="target"/></label><p v-if="autoNaming&&layoutFolder" class="modal-note layout-preview">将创建：{{target.replace(/\/$/,'')}}/{{layoutFolder}}{{selected.media?.type==='tv'?'/Season NN':''}}</p><p v-if="autoNaming&&nestedTarget" class="error-text">所选目录看起来已是标题文件夹，将在其中再建一层；建议选择上一级分类目录。</p><FolderPicker :request="api" v-model="target" :disabled="submitBusy" @editing="folderEditing=$event" @renamed="settings.last_target=$event"/><template v-if="selected.kind==='share'"><button class="outline wide" @click="preview" :disabled="busy">预览分享并选择内容</button><div v-if="sharePreviewed" class="share-list"><label v-for="i in shareItems" :key="i.id"><input v-model="shareSelection" type="checkbox" :value="i.id"/><Folder v-if="i.is_dir" :size="15"/><Film v-else :size="15"/><span>{{i.name}}</span><small>{{i.is_dir?'目录':formatBytes(i.size)}}</small></label><p v-if="!shareItems.length">分享中没有可转存内容</p></div><small v-else>{{autoNaming?'默认转存整份分享，保留目录层级；视频和明确关联的字幕规范改名。合集请按影片拆分入库。':'默认转存整份分享，保留原文件名和目录层级。'}}</small></template><NamingPreview v-if="autoNaming" :request="api" :input="namingInput" :available="selected.kind==='share'||!!magnetSelection" :llm-enabled="!!settings.llm_enabled" @approved="namingApproval=$event" @blocked="namingBlocked=$event"/><p class="modal-note">{{autoNaming?'115 下载完成后自动筛掉广告和无关文件，按 TMDB 规范命名并整理到标题文件夹，通过校验即同步 STRM 并通知 Emby；无法确定时暂停到任务详情。':'文件到位后保留原文件名和目录，同步 STRM 并通知 Emby。'}}</p><div class="modal-footer"><p v-if="error" class="error-text">{{error}}</p><button class="primary wide" @click="submit" :disabled="submitBusy||busy||(autoNaming&&namingBlocked)||(autoNaming&&!selected.media)||folderEditing||(selected.kind==='magnet'&&!magnetReady)"><Loader2 v-if="submitBusy" class="spin" :size="17"/><Download v-else :size="17"/>{{submitBusy?'提交中':'确认入库'}}</button></div></div></div>
  <div v-if="manual" class="modal-backdrop" @click.self="manual=false"><form class="modal" @submit.prevent="addManual"><button class="modal-close icon-button" type="button" @click="manual=false"><X :size="20"/></button><span class="eyebrow">DIRECT LINK</span><h2>粘贴资源链接</h2><label>磁力链接或 115 分享<textarea v-model="manualLink" required placeholder="magnet:?xt=… 或 https://115.com/s/…"/></label><label>资源名称（可选）<input v-model="manualTitle"/></label><button class="primary wide">选择入库目录 <ArrowRight :size="17"/></button></form></div>
  <div v-if="detail" class="modal-backdrop" @click.self="detail=null"><div class="modal"><button class="modal-close icon-button" @click="detail=null"><X :size="20"/></button><span class="eyebrow">TASK JOURNEY</span><h2>任务详情</h2><p class="selected-title">{{detail.title}}</p><div class="task-status" :class="detail.state">{{labels[detail.state]}}</div><p class="task-path">{{detail.target}}</p><p v-if="detail.error" class="error-text">{{detail.error}}</p><div class="timeline"><div v-for="(event,i) in detail.events" :key="i"><span/><p><b>{{labels[event.state]||event.state}}</b><small>{{formatTime(event.created)}}</small></p></div></div><p v-if="detail.naming?.version===2&&detail.naming.excluded_count" class="modal-note">已排除 {{detail.naming.excluded_count}} 个广告、样片或未选文件，保留在下载暂存目录。</p><template v-if="detail.selection&&detail.naming?.version!==2"><p class="modal-note">选中 {{detail.selection.selected_count}} 个文件入库，{{detail.selection.retained_count}} 个未选文件保留在下载暂存目录。</p><p v-if="detail.selection.download_staging" class="task-path">下载暂存目录：{{detail.selection.download_staging}}</p></template><p v-if="detail.naming&&detail.staging" class="task-path">暂存目录：{{detail.staging}}</p><TaskNaming v-if="detail.naming" :request="api" :task-id="detail.id" :naming="detail.naming" :llm-enabled="!!settings.llm_enabled" @updated="refreshDetail"/><template v-if="detail.can_change_target"><label>更换为无冲突的媒体子目录<input v-model="renameTarget"/></label><button class="primary wide" @click="changeTarget">更换目录并继续</button></template><p v-if="detail.state==='completed'" class="modal-note">115 文件与 STRM 已到位，Emby 已接受刷新通知。刮削进度以 Emby 为准。</p></div></div>
</template>
